-- Parity test for Cognos report Industrial_Load_Profile (cluster BIL_020, 4 runs/day)
-- Generated by SemLift 1.0.0; tolerance +/-0.5% on totals
-- Measures whose numbers are expected to change (F6 aggregation correction): max_peak_demand_kw
WITH cognos AS (
    SELECT dt.FULL_DATE AS full_date, dt.MONTH_NAME AS month_name, tariff.TARIFF_TYPE AS tariff_type, customer.CUSTOMER_NAME AS customer_name, SUM(meter_reading.CONSUMPTION_KWH) AS total_consumption_kwh, SUM(meter_reading.PEAK_DEMAND_KW) AS max_peak_demand_kw, SUM(meter_reading.REACTIVE_KVARH) AS total_reactive_kvarh
    FROM CORE.FCT_METER_READING meter_reading
    JOIN CORE.DIM_DATE dt ON meter_reading.DATE_KEY = dt.DATE_KEY
    JOIN CORE.DIM_TARIFF tariff ON meter_reading.TARIFF_ID = tariff.TARIFF_ID
    JOIN CORE.DIM_METER meter ON meter_reading.METER_ID = meter.METER_ID
    JOIN CORE.DIM_CUSTOMER customer ON meter.CUSTOMER_ID = customer.CUSTOMER_ID
    WHERE dt.FISCAL_YEAR = 2026
    GROUP BY 1, 2, 3, 4
),
semantic AS (
    SELECT * FROM SEMANTIC_VIEW(
        SEM.SV_METER_CONSUMPTION
        DIMENSIONS dt.full_date, dt.month_name, tariff.tariff_type, customer.customer_name
        METRICS meter_reading.total_consumption_kwh, meter_reading.max_peak_demand_kw, meter_reading.total_reactive_kvarh
    ) WHERE fiscal_year = 2026
)
SELECT
    (SELECT COUNT(*) FROM cognos) AS cognos_rows,
    (SELECT COUNT(*) FROM semantic) AS semantic_rows,
    SUM(c.total_consumption_kwh) AS cognos_total_consumption_kwh, SUM(s.total_consumption_kwh) AS semantic_total_consumption_kwh,
    IFF(ABS(COALESCE(SUM(s.total_consumption_kwh), 0) - COALESCE(SUM(c.total_consumption_kwh), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_consumption_kwh), 0)), 'PASS', 'FAIL') AS status_total_consumption_kwh,
    SUM(c.max_peak_demand_kw) AS cognos_max_peak_demand_kw, SUM(s.max_peak_demand_kw) AS semantic_max_peak_demand_kw,
    IFF(ABS(COALESCE(SUM(s.max_peak_demand_kw), 0) - COALESCE(SUM(c.max_peak_demand_kw), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.max_peak_demand_kw), 0)), 'PASS', 'EXPECTED_CHANGE (F6)') AS status_max_peak_demand_kw,
    SUM(c.total_reactive_kvarh) AS cognos_total_reactive_kvarh, SUM(s.total_reactive_kvarh) AS semantic_total_reactive_kvarh,
    IFF(ABS(COALESCE(SUM(s.total_reactive_kvarh), 0) - COALESCE(SUM(c.total_reactive_kvarh), 0)) <= 0.5 / 100 * ABS(NULLIF(SUM(c.total_reactive_kvarh), 0)), 'PASS', 'FAIL') AS status_total_reactive_kvarh
FROM cognos c
FULL OUTER JOIN semantic s ON c.full_date IS NOT DISTINCT FROM s.full_date AND c.month_name IS NOT DISTINCT FROM s.month_name AND c.tariff_type IS NOT DISTINCT FROM s.tariff_type AND c.customer_name IS NOT DISTINCT FROM s.customer_name;
